from typing import List

def factorize(n: int) -> List[int]:
    """Return the prime factors of n from smallest to largest, with repetitions."""
    if n < 1:
        raise ValueError("n must be a positive integer")

    factors = []

    while n % 2 == 0 and n > 1:
        factors.append(2)
        n //= 2

    divisor = 3
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 2

    if n > 1:
        factors.append(n)

    return factors
