import math

def is_prime(n: int) -> bool:
    """Return True if n is prime, otherwise False."""
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3

    limit = math.isqrt(n)
    candidate = 5

    while candidate <= limit:
        if n % candidate == 0 or n % (candidate + 2) == 0:
            return False
        candidate += 6

    return True
```

