import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    """
    return sum(coeff * math.pow(x, i) for i, coeff in enumerate(xs))


def find_zero(xs: list):
    """Find one x such that poly(xs, x) == 0."""
    def f(x):
        result = 0.0
        for coeff in reversed(xs):
            result = result * x + coeff
        return result

    left, right = -1.0, 1.0
    f_left, f_right = f(left), f(right)

    # Expand the interval until the endpoints have opposite signs.
    while (f_left > 0 and f_right > 0) or (f_left < 0 and f_right < 0):
        left *= 2.0
        right *= 2.0
        f_left, f_right = f(left), f(right)

    if f_left == 0:
        return left
    if f_right == 0:
        return right

    # Bisection method.
    for _ in range(200):
        mid = (left + right) / 2.0
        f_mid = f(mid)

        if f_mid == 0:
            return mid

        if (f_left > 0 and f_mid > 0) or (f_left < 0 and f_mid < 0):
            left = mid
            f_left = f_mid
        else:
            right = mid
            f_right = f_mid

    return (left + right) / 2.0
