def triples_sum_to_zero(l: list) -> bool:
    """
    Return True if there are three distinct elements in l that sum to zero,
    and False otherwise. Distinct elements means elements at distinct indices.
    """
    n = len(l)
    if n < 3:
        return False

    nums = sorted(l)

    for i in range(n - 2):
        # Skip duplicate starting values to avoid redundant checks.
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1

    return False
