def fibfib(n: int) -> int:
    """Compute the n-th number in the FibFib sequence."""
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 1

    # Represents fibfib(n-3), fibfib(n-2), fibfib(n-1)
    a, b, c = 0, 0, 1

    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c

    return c
```

```python
def fibfib(n: int):
    if n < 2:
        return 0
    if n == 2:
        return 1

    a, b, c = 0, 0, 1  # fibfib(0), fibfib(1), fibfib(2)

    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c

    return c
```

