def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if x == 1:
        return True  # n ** 0 == 1
    if n == -1:
        return x == -1
    if n == 0:
        return x == 0

    power = n
    while abs(power) < abs(x):
        power *= n

    return power == x
