from math import isqrt

def prime_length(string):
    """Return True if the length of string is a prime number, otherwise False."""
    n = len(string)

    if n < 2:
        return False

    if n % 2 == 0:
        return n == 2

    for divisor in range(3, isqrt(n) + 1, 2):
        if n % divisor == 0:
            return False

    return True
```

