from math import isqrt


def is_prime(n: int) -> bool:
    """Return True if n is a prime number."""
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    divisor = 5
    while divisor <= isqrt(n):
        if n % divisor == 0 or n % (divisor + 2) == 0:
            return False
        divisor += 6

    return True


def skjkasdkd(lst):
    """Find the largest prime in lst and return the sum of its digits."""
    largest_prime = -1

    for value in lst:
        if value > largest_prime and is_prime(value):
            largest_prime = value

    if largest_prime == -1:
        return 0

    return sum(int(digit) for digit in str(largest_prime))
```

