UPPERCASE_VOWELS = frozenset("AEIOU")

def count_upper(s: str) -> int:
    """
    Count the number of uppercase vowels in even indices of s.

    Even indices are 0, 2, 4, ...
    """
    return sum(
        char in UPPERCASE_VOWELS
        for index, char in enumerate(s)
        if index % 2 == 0
    )
```

